import{stats}from"../components/StatsChart/StatsChart";export var months=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];export var formatCountAxis=function(t,r){return t};export var formatMinsAxis=function(t,r){return Math.floor(t/60).toString()+" hr"};export function formatMinutes(t){var r=Math.floor(t/60).toString(),n=Math.floor(t%60).toString();return"0"!==r?r+" hr, "+n+" min":n+" min"}export function legendFormatter(t,r){return"light"===currentTheme?"<div style=\"font-family:'Open Sans',sans-serif;font-size:12px;padding:2px;padding-right:15px;color:#27272A\">"+t+"</div>":"<div style=\"font-family:'Open Sans',sans-serif;font-size:12px;padding:2px;padding-right:15px;color:#fafafa\">"+t+"</div>"}